class _ResultsState extends State<Results>{List<Map<String,dynamic>> rows=[];bool loading=true;int? wid;Future<void> load()async{try{if(widget.wilaya!='الكل'){final x=await db.from('wilayas').select('id').eq('name_ar',widget.wilaya).maybeSingle();wid=x?['id'];}if(widget.workers){var q=db.from('job_seeker_profiles').select('id,profession_id,wilaya_id,experience_years,age,gender,phone,skills,professions(name_ar),wilayas(name_ar)');if(wid!=null)q=q.eq('wilaya_id',wid!);if(widget.gender!='الكل')q=q.eq('gender',widget.gender=='ذكر'?'male':'female');q=q.gte('experience_years',widget.minExp).gte('age',widget.minAge).lte('age',widget.maxAge);final d=await q;rows=List<Map<String,dynamic>>.from(d);}else{var q=db.from('job_offers').select('id,title,description,vacancies,experience_years,min_age,max_age,gender,profession_id,wilaya_id,professions(name_ar),wilayas(name_ar)').eq('status','published');if(wid!=null)q=q.eq('wilaya_id',wid!);if(widget.gender!='الكل')q=q.eq('gender',widget.gender=='ذكر'?'male':'female');q=q.gte('experience_years',widget.minExp);final d=await q;rows=List<Map<String,dynamic>>.from(d);}if(widget.profession.isNotEmpty)rows=rows.where((r)=>(r['professions']?['name_ar']??'').toString().contains(widget.profession)||(r['title']??'').toString().contains(widget.profession)).toList();}catch(e){if(mounted)toast(context,'خطأ: ${clean(e)}');}finally{if(mounted)setState(()=>loading=false);}}@override void initState(){super.initState();load();}Future<void> apply(String id)async{try{await db.from('job_applications').insert({'job_offer_id':id,'applicant_id':db.auth.currentUser!.id});toast(context,'تم إرسال طلب التقديم');}catch(e){toast(context,'تعذر التقديم: ${clean(e)}');}}Future<void> invite(String id,dynamic pid)async{try{await db.from('invitations').insert({'sender_id':db.auth.currentUser!.id,'receiver_id':id,'profession_id':pid,'message':'دعوة للتواصل عبر أرواح تخدم'});toast(context,'تم إرسال الدعوة');}catch(e){toast(context,'تعذر إرسال الدعوة: ${clean(e)}');}}@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:Text(widget.workers?'العمال':'فرص العمل')),body:loading?const Center(child:CircularProgressIndicator()):rows.isEmpty?const Center(child:Text('لا توجد نتائج')):ListView.builder(padding:const EdgeInsets.all(12),itemCount:rows.length,itemBuilder:(_,i){final r=rows[i];final p=r['professions']?['name_ar']??'غير محدد',w=r['wilayas']?['name_ar']??'غير محدد';return Card(child:ListTile(leading:CircleAvatar(child:Icon(widget.workers?Icons.person:Icons.work)),title:Text(widget.workers?p.toString():(r['title']??p).toString()),subtitle:Text('$w\nالخبرة: ${r['experience_years']??'-'} | العمر: ${r['age']??'-'}'),isThreeLine:true,trailing:FilledButton(onPressed:()=>widget.workers?invite(r['id'].toString(),r['profession_id']):apply(r['id'].toString()),child:Text(widget.workers?'دعوة':'تقديم'))));}));}}

