class Invitations extends StatefulWidget{const Invitations({super.key});@override State<Invitations> createState()=>_InvitationsState();}
class _InvitationsState extends State<Invitations>{Future<List<Map<String,dynamic>>> load()async{final id=db.auth.currentUser!.id;return List<Map<String,dynamic>>.from(await db.from('invitations').select('id,sender_id,receiver_id,status,message,professions(name_ar),created_at').or('sender_id.eq.$id,receiver_id.eq.$id').order('created_at',ascending:false));}Future<void> respond(String id,String status)async{try{await db.from('invitations').update({'status':status,'responded_at':DateTime.now().toIso8601String()}).eq('id',id);setState((){});}catch(e){toast(context,'تعذر التحديث: ${clean(e)}');}}Future<void> chat(String other)async{try{final me=db.auth.currentUser!.id;final ex=await db.from('conversation_participants').select('conversation_id').eq('user_id',me);String? cid;for(final r in List<Map<String,dynamic>>.from(ex)){final id=r['conversation_id'].toString();final q=await db.from('conversation_participants').select('user_id').eq('conversation_id',id).eq('user_id',other);if(q.isNotEmpty){cid=id;break;}}if(cid==null){final c=await db.from('conversations').insert({}).select('id').single();cid=c['id'].toString();await db.from('conversation_participants').insert([{'conversation_id':cid,'user_id':me},{'conversation_id':cid,'user_id':other}]);}if(mounted)Navigator.push(context,MaterialPageRoute(builder:(_)=>Chat(cid!)));}catch(e){toast(context,'تعذر فتح المحادثة: ${clean(e)}');}}@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:const Text('الدعوات')),body:FutureBuilder(future:load(),builder:(_,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());final a=List<Map<String,dynamic>>.from(s.data??[]);final me=db.auth.currentUser!.id;if(a.isEmpty)return const Center(child:Text('لا توجد دعوات'));return ListView.builder(itemCount:a.length,itemBuilder:(_,i){final r=a[i];final incoming=r['receiver_id']==me;return Card(child:ListTile(title:Text(incoming?'دعوة واردة':'دعوة مرسلة'),subtitle:Text('${r['professions']?['name_ar']??'تواصل'}\nالحالة: ${r['status']}'),trailing:incoming&&r['status']=='pending'?Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>respond(r['id'].toString(),'accepted'),icon:const Icon(Icons.check,color:Colors.green)),IconButton(onPressed:()=>respond(r['id'].toString(),'rejected'),icon:const Icon(Icons.close,color:Colors.red))]):r['status']=='accepted'?IconButton(onPressed:()=>chat(incoming?r['sender_id'].toString():r['receiver_id'].toString()),icon:const Icon(Icons.chat)):null));});})));}}

class Chats extends StatelessWidget{const Chats({super.key});@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:const Text('المحادثات')),body:FutureBuilder(future:db.from('conversation_participants').select('conversation_id').eq('user_id',db.auth.currentUser!.id),builder:(_,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());final a=List<Map<String,dynamic>>.from(s.data??[]);if(a.isEmpty)return const Center(child:Text('لا توجد محادثات'));return ListView.builder(itemCount:a.length,itemBuilder:(_,i)=>ListTile(leading:const Icon(Icons.chat),title:Text('محادثة ${i+1}'),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>Chat(a[i]['conversation_id'].toString())))));})));}}
class Chat extends StatefulWidget{final String id;const Chat(this.id,{super.key});@override State<Chat> createState()=>_ChatState();}
class _ChatState extends State<Chat>{final t=TextEditingController();Future<List<Map<String,dynamic>>> load()async=>List<Map<String,dynamic>>.from(await db.from('messages').select('*').eq('conversation_id',widget.id).order('created_at'));Future<void> send()async{if(t.text.trim().isEmpty)return;try{await db.from('messages').insert({'conversation_id':widget.id,'sender_id':db.auth.currentUser!.id,'body':t.text.trim()});t.clear();setState((){});}catch(e){toast(context,'تعذر الإرسال: ${clean(e)}');}}@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:const Text('المحادثة')),body:Column(children:[Expanded(child:FutureBuilder(future:load(),builder:(_,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());final a=List<Map<String,dynamic>>.from(s.data??[]);return ListView.builder(itemCount:a.length,itemBuilder:(_,i)=>ListTile(title:Text(a[i]['body'].toString())));})),Row(children:[Expanded(child:TextField(controller:t,decoration:deco('اكتب رسالة'))),IconButton(onPressed:send,icon:const Icon(Icons.send))])]));}}

class Notifications extends StatelessWidget{const Notifications({super.key});@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:const Text('الإشعارات')),body:FutureBuilder(future:db.from('notifications').select('*').eq('user_id',db.auth.currentUser!.id).order('created_at',ascending:false),builder:(_,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());final a=List<Map<String,dynamic>>.from(s.data??[]);if(a.isEmpty)return const Center(child:Text('لا توجد إشعارات'));return ListView.builder(itemCount:a.length,itemBuilder:(_,i)=>ListTile(leading:const Icon(Icons.notifications),title:Text((a[i]['title']??'').toString()),subtitle:Text((a[i]['body']??'').toString())));})));}}
class Profile extends StatefulWidget{const Profile({super.key});@override State<Profile> createState()=>_ProfileState();}
class _ProfileState extends State<Profile>{final name=TextEditingController();String role='job_seeker';bool loading=true;@override void initState(){super.initState();load();}Future<void> load()async{final r=await db.from('profiles').select('*').eq('id',db.auth.currentUser!.id).maybeSingle();if(r!=null){name.text=(r['full_name']??'').toString();role=(r['account_type']??'job_seeker').toString();}if(mounted)setState(()=>loading=false);}Future<void> save()async{try{await db.from('profiles').update({'full_name':name.text.trim(),'updated_at':DateTime.now().toIso8601String()}).eq('id',db.auth.currentUser!.id);toast(context,'تم الحفظ');}catch(e){toast(context,'تعذر الحفظ: ${clean(e)}');}}String ar(String x)=>x=='job_seeker'?'باحث عن عمل':x=='investor'?'مستثمر':x=='project_owner'?'صاحب مشروع':'صاحب عمل / شركة';@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:const Text('حسابي')),body:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(18),children:[const CircleAvatar(radius:45,child:Icon(Icons.person,size:50)),const SizedBox(height:20),TextField(controller:name,decoration:deco('الاسم')),ListTile(leading:const Icon(Icons.badge),title:const Text('نوع الحساب'),subtitle:Text(ar(role))),FilledButton(onPressed:save,child:const Text('حفظ'))])));}}
